import pytest

def test_partition_all_invalid_len():
    import pytest
    from toolz.itertoolz import partition_all, no_pad

    class BadLengthSequence:
        def __init__(self, data, length):
            self.data = data
            self._length = length

        def __iter__(self):
            return iter(self.data)

        def __len__(self):
            return self._length

    # Case 1: __len__ reports more elements than actual (too long)
    seq_long = BadLengthSequence([0, 1, 2, 3, 4], 7)
    try:
        result_long = list(partition_all(10, seq_long))
    except Exception as e:
        pytest.fail(f"partition_all raised {type(e).__name__}: {e}")
    assert result_long == [(0, 1, 2, 3, 4)]
    for batch in result_long:
        assert no_pad not in batch

    # Case 2: __len__ reports fewer elements than actual (too short)
    seq_short = BadLengthSequence([0, 1, 2, 3, 4], 3)
    try:
        result_short = list(partition_all(10, seq_short))
    except Exception as e:
        pytest.fail(f"partition_all raised {type(e).__name__}: {e}")
    assert result_short == [(0, 1, 2, 3, 4)]
    for batch in result_short:
        assert no_pad not in batch

    # Case 3: __len__ accurate (should still work)
    seq_exact = BadLengthSequence([0, 1, 2, 3, 4], 5)
    try:
        result_exact = list(partition_all(10, seq_exact))
    except Exception as e:
        pytest.fail(f"partition_all raised {type(e).__name__}: {e}")
    assert result_exact == [(0, 1, 2, 3, 4)]
    for batch in result_exact:
        assert no_pad not in batch

    # Case 4: Multiple batches with invalid __len__
    seq_multi = BadLengthSequence(list(range(12)), 15)  # 12 elements, len=15
    try:
        result_multi = list(partition_all(5, seq_multi))
    except Exception as e:
        pytest.fail(f"partition_all raised {type(e).__name__}: {e}")
    expected_multi = [tuple(range(5)), tuple(range(5, 10)), (10, 11)]
    assert result_multi == expected_multi
    for batch in result_multi:
        assert no_pad not in batch

